import React, { useState } from "react";
import { motion } from "framer-motion";
import Cursor from "./Cursor";

export default function LandingPage() {
  const [menuOpen, setMenuOpen] = useState(false);

  const handleScroll = (id) => {
    const section = document.getElementById(id);

    if (section) {
      section.scrollIntoView({
        behavior: "smooth",
        block: "start",
      });
    }

    setMenuOpen(false);
  };

  return (
     <> 
     <Cursor /> 
     <div className="bg-black text-white font-[Inter]">
      {/* NAVBAR */}
      <nav className="fixed w-full z-50 bg-black/90 border-b border-neutral-900">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-10 h-16 flex items-center justify-between">
          <div className="flex items-center">
            <img
              src="/gfc-logo.png"
              alt="GFC Logo"
              className="
      h-[40px]
      sm:h-[48px]
      md:h-[56px]
      lg:h-[64px]
      xl:h-[100px]
      object-contain
    "
            />
          </div>

          {/* DESKTOP */}
          <ul className="hidden md:flex gap-8 text-xs uppercase tracking-wider">
            {navItems.map((item) => (
              <li
                key={item.id}
                onClick={() => handleScroll(item.id)}
                className="hover:text-red-500  transition"
              >
                {item.name}
              </li>
            ))}
          </ul>

          {/* MOBILE */}
          <button onClick={() => setMenuOpen(!menuOpen)} className="md:hidden">
            ☰
          </button>

          <button className="hidden sm:block bg-red-600 px-4 py-2 text-xs font-semibold">
            GET TICKETS
          </button>
        </div>

        {/* MOBILE MENU */}
        {menuOpen && (
          <div className="md:hidden bg-black border-t border-neutral-800 flex flex-col items-center py-6 gap-4">
            {navItems.map((item) => (
              <div
                key={item.id}
                onClick={() => handleScroll(item.id)}
                className=" hover:text-red-500"
              >
                {item.name}
              </div>
            ))}
          </div>
        )}
      </nav>
      {/* HERO */}
      <section
        id="home"
        className="relative pt-16 flex items-center bg-black overflow-hidden"
      >
        {/* BACKGROUND IMAGE (RIGHT SIDE) */}
        <div className="absolute inset-0 flex justify-end pointer-events-none">
          <img
            src="/fighter.png"
            alt="fighter"
            className="
        w-[90%]
        sm:w-[70%]
        md:w-[60%]
        lg:w-[55%]
        xl:w-[50%]
        max-w-[900px]
        object-contain
      "
          />
        </div>

        {/* GRADIENT OVERLAY */}
        <div className="absolute inset-0 bg-gradient-to-r from-black via-black/90 to-transparent" />

        {/* CONTENT */}
        <div className="relative z-10 max-w-7xl mx-auto px-4 sm:px-6 lg:px-10 w-full">
          {/* TEXT AREA (acts like your 40%) */}

          <div className=" w-full max-w-[95%] sm:max-w-[600px] lg:max-w-[700px] pt-6 sm:pt-8 md:pt-10 lg:pt-14 xl:pt-16 pl-3 sm:pl-6 md:pl-10 lg:pl-16 xl:pl-20 ">
            <p className="text-red-500 text-xs uppercase tracking-[2px] mb-4">
              GFC GLOBAL 1: ORIGIN
            </p>

            <h1
              className="
        font-[Anton]
        italic
        uppercase
        tracking-[1px]
        leading-none
        text-[32px]
        sm:text-[48px]
        md:text-[70px]
        lg:text-[95px]
        xl:text-[120px]
      "
            >
              <span className="block">FIGHTS.</span>
              <span className="block">STORIES.</span>
              <span className="block text-red-500">LEGENDS.</span>
            </h1>

            <p className="mt-4 text-gray-300 text-sm sm:text-base">
              India’s Next Combat Sports Movement
            </p>

            <div className="flex flex-col sm:flex-row gap-3 mt-6">
              <button className="bg-red-600 px-5 py-3 text-xs sm:text-sm font-semibold">
                GET TICKETS
              </button>

              <button className="border border-white px-5 py-3 text-xs sm:text-sm">
                ▶ WATCH TRAILER
              </button>
            </div>
          </div>
        </div>
      </section>
      {/* FEATURES */}
      <section id="about" className="border-t border-neutral-900">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-10 py-12 grid grid-cols-2 sm:grid-cols-3 lg:grid-cols-5 gap-6 text-center">
          {features.map((item, i) => (
            <div
              key={i}
              className="
    border-r-2 border-[#333]
    pr-4
    last:border-none
  "
            >
              <i className={`fa ${item.icon} text-red-500 text-2xl mb-3`} />

              <h3 className="text-xs font-bold uppercase mb-1">{item.title}</h3>

              <p className="text-xs text-gray-500">{item.desc}</p>
            </div>
          ))}
        </div>
      </section>
      FIGHTS{" "}
      <section
        id="fights"
        className="py-24 bg-black border-t border-neutral-900"
      >
        {" "}
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-10">
          {" "}
          <h2 className="text-4xl font-[Anton] uppercase mb-12">
            {" "}
            Upcoming <span className="text-red-500">Fights</span>{" "}
          </h2>{" "}
          <div className="grid md:grid-cols-3 gap-8">
            {" "}
            {fightImages.map((img, i) => (
              <div
                key={i}
                className="group relative rounded-lg overflow-hidden"
              >
                {" "}
                <img
                  src={img}
                  className="h-56 w-full object-cover group-hover:scale-110 transition duration-500"
                />{" "}
                <div className="absolute inset-0 bg-black/60 flex flex-col justify-end p-5">
                  {" "}
                  <h3 className="font-bold text-lg">
                    Fight Night {i + 1}
                  </h3>{" "}
                  <p className="text-sm text-gray-300">Elite matchups</p>{" "}
                </div>{" "}
              </div>
            ))}{" "}
          </div>{" "}
        </div>{" "}
      </section>{" "}
      {/* FIGHTERS */}{" "}
      <section
        id="fighters"
        className="py-24 bg-black border-t border-neutral-900"
      >
        {" "}
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-10">
          {" "}
          <h2 className="text-4xl font-[Anton] uppercase mb-12">
            {" "}
            Our <span className="text-red-500">Fighters</span>{" "}
          </h2>{" "}
          <div className="grid sm:grid-cols-2 md:grid-cols-4 gap-8">
            {" "}
            {fighterImages.map((img, i) => (
              <div key={i} className="group text-center">
                {" "}
                <div className="overflow-hidden rounded-lg">
                  {" "}
                  <img
                    src={img}
                    className="h-48 w-full object-cover group-hover:scale-110 transition duration-500"
                  />{" "}
                </div>{" "}
                <h3 className="mt-3 font-semibold">Fighter {i + 1}</h3>{" "}
              </div>
            ))}{" "}
          </div>{" "}
        </div>{" "}
      </section>{" "}
      {/* ORIGIN */}{" "}
      <section
        id="origin"
        className="py-24 bg-black border-t border-neutral-900 text-center"
      >
        {" "}
        <div className="max-w-5xl mx-auto px-4">
          {" "}
          <h2 className="text-4xl font-[Anton] uppercase mb-8">
            {" "}
            GFC <span className="text-red-500">Origin</span>{" "}
          </h2>{" "}
          <img
            src="https://images.pexels.com/photos/4753986/pexels-photo-4753986.jpeg"
            className="w-full h-72 object-cover rounded-lg mb-8"
          />{" "}
          <p className="text-gray-400 text-lg leading-relaxed">
            {" "}
            GFC is India’s next combat sports movement — building fighters,
            creating legends, and shaping the future of combat sports
            entertainment.{" "}
          </p>{" "}
        </div>{" "}
      </section>{" "}

{/* SPONSORS */}{" "}
<section id="sponsors" className="py-24 bg-black border-t border-neutral-900 overflow-hidden">
  <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-10">

    {/* TITLE */}
    <motion.h2
      initial={{ opacity: 0, y: 40 }}
      whileInView={{ opacity: 1, y: 0 }}
      transition={{ duration: 0.6 }}
      className="text-4xl font-[Anton] uppercase mb-12 text-center"
    >
      Our <span className="text-red-500">Sponsors</span>
    </motion.h2>

    {/* AUTO SCROLL CONTAINER */}
    <div className="relative overflow-hidden">

      <motion.div
        className="flex gap-10 w-max"
        animate={{ x: ["0%", "-50%"] }}
        transition={{
          repeat: Infinity,
          duration: 15,
          ease: "linear",
        }}
      >

        {[...sponsorLogos, ...sponsorLogos].map((logo, i) => (

<div
  key={i}
  className="
    min-w-[150px]
    bg-white
    p-6
    rounded-lg
    flex items-center justify-center
    transition
    hover:scale-110
    hover:bg-gray-100
    hover:shadow-[0_0_20px_rgba(255,0,0,0.3)]
  "
>


            <img
              src={logo}
              alt="sponsor"
              className="
                h-12
                object-contain

                transition duration-300
              "
            />
          </div>
        ))}

      </motion.div>

    </div>

  </div>
</section>




      {/* NEWS */}{" "}
      <section id="news" className="py-24 bg-black border-t border-neutral-900">
        {" "}
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-10">
          {" "}
          <h2 className="text-4xl font-[Anton] uppercase mb-12">
            {" "}
            Latest <span className="text-red-500">News</span>{" "}
          </h2>{" "}
          <div className="grid md:grid-cols-3 gap-8">
            {" "}
            {newsImages.map((img, i) => (
              <div
                key={i}
                className="bg-neutral-900 rounded-lg overflow-hidden hover:bg-neutral-800 transition"
              >
                {" "}
                <img src={img} className="h-44 w-full object-cover" />{" "}
                <div className="p-5">
                  {" "}
                  <h3 className="font-semibold mb-2">News {i + 1}</h3>{" "}
                  <p className="text-gray-400 text-sm">
                    {" "}
                    Breaking updates from GFC events and fighters.{" "}
                  </p>{" "}
                </div>{" "}
              </div>
            ))}{" "}
          </div>{" "}
        </div>{" "}
      </section>{" "}
      {/* CONTACT */}{" "}
      <section
        id="contact"
        className="py-24 bg-black border-t border-neutral-900"
      >
        {" "}
        <div className="max-w-xl mx-auto px-4 text-center">
          {" "}
          <h2 className="text-4xl font-[Anton] uppercase mb-8">
            {" "}
            Contact <span className="text-red-500">Us</span>{" "}
          </h2>{" "}
          <form className="space-y-4">
            {" "}
            <input
              className="w-full p-3 bg-neutral-900 border border-neutral-700 focus:outline-none focus:border-red-500"
              placeholder="Your Name"
            />{" "}
            <input
              className="w-full p-3 bg-neutral-900 border border-neutral-700 focus:outline-none focus:border-red-500"
              placeholder="Email"
            />{" "}
            <textarea
              className="w-full p-3 bg-neutral-900 border border-neutral-700 focus:outline-none focus:border-red-500"
              rows="4"
              placeholder="Message"
            />{" "}
            <button className="w-full bg-red-600 py-3 font-semibold hover:bg-red-700 transition">
              {" "}
              SEND MESSAGE{" "}
            </button>{" "}
          </form>{" "}
        </div>{" "}
      </section>
      {/* FOOTER */}
      <footer className="text-center text-xs text-gray-500 py-6 border-t border-neutral-900">
        © {new Date().getFullYear()} GFC. All rights reserved.
      </footer>
    </div>
    </>
  );
}

